function pipe(...fns) {
  return (input) => fns.reduce((acc, fn) => fn(acc), input);
}

function validateOrder(order) { return { ...order, validated: true }; }
function priceOrder(order) { return { ...order, price: 100 }; }
function confirmOrder(order) { return { ...order, confirmed: true }; }

const placeOrder = pipe(validateOrder, priceOrder, confirmOrder);

console.log(placeOrder({ customerId: 'C1' }));

